"""Shim for ToplevelWindow used by InterOps.

Provides a minimal `ToplevelWindow` wrapper exposing `byObject()` and
`moveTo()` used by the framework. It uses `squishtest` when available.
"""
from typing import Any


class ToplevelWindow:
    def __init__(self, obj: Any):
        self._obj = obj

    @classmethod
    def byObject(cls, obj: Any) -> 'ToplevelWindow':
        return cls(obj)

    def moveTo(self, x: int, y: int) -> None:
        try:
            import squishtest as sq
            fn = getattr(sq, '_squish_window_move', None)
            if callable(fn):
                try:
                    fn(self._obj, x, y)
                    return
                except Exception:
                    pass
            if hasattr(sq, 'setForegroundWindow'):
                try:
                    sq.setForegroundWindow(self._obj)
                except Exception:
                    pass
        except Exception:
            # no-op if squishtest not present
            return
